################################################################################
# 03_region_proportions.R
# Region proportions per ILAE score and sample
# Input: 07_seumerged.rds generated by 01_domainIdentification.R (Section 8)
# Output: two PNG plots, 09_n_spots_regions.rds, and session information
#
# Original author: Mathias Delhaye, October 2026
# Code cleanup and standardization: Larissa Kraus (October 2026)

### 0) Setup -------------------------------------------------------------------
suppressPackageStartupMessages({
        library(conflicted)
        library(tidyverse)
        library(Seurat)
})

### PACKAGE CONFLICTS ---------------------------------------------------------
conflicted::conflicts_prefer(dplyr::filter, dplyr::select, dplyr::rename, dplyr::lag)


### 1) User-editable config ----------------------------------------------------
cfg <- list(
        # INPUT: seumerged output of 01_domainIdentification.R (Section 8).
        # Required only if a valid 'seumerged' object is not already in the environment.
        seumerged_file = NA_character_,
        
        # OUTPUT: choose directories independently; both are created if absent.
        rds_dir = NA_character_,
        fig_dir = NA_character_,
        
        # TRUE: reuse seumerged from the current R environment if it is a Seurat object.
        # FALSE: always read the RDS file above.
        
        f_n_spots_regions = "09_n_spots_regions.rds",
        
        col_regions = setNames(
                c("#3D0F99", "#C7B8E6", "#0F8299", "#B8DEE6", "#54990F", "#CFE6B8",
                  "#333333", "#990F26", "#CCAA7A", "#99600F", "#FFD300"),
                c("GCL", "ML", "CA2_CA4", "CA1", "SL.SR.SLM", "GABA", "SUB", "WM", "pia", "vascular", "void")
        ),
        region_levels = c("CA1", "CA2_CA4", "GABA", "GCL", "ML", "pia", "SL.SR.SLM", "SUB", "vascular", "WM", "void"),
        ILAE_levels = c("P", "ILAE0", "ILAE1", "ILAE2", "ILAE3")
)

dir.create(cfg$rds_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(cfg$fig_dir, recursive = TRUE, showWarnings = FALSE)

### 2) Helper functions --------------------------------------------------------

# Reuse an existing object in the global environment; otherwise load its RDS file.
# object_name: name to assign; file: user-configured RDS path; class: optional class check.
load_if_missing <- function(object_name, file, class = NULL) {
        if (exists(object_name, envir = .GlobalEnv, inherits = FALSE)) {
                obj <- get(object_name, envir = .GlobalEnv)
                if (is.null(class) || inherits(obj, class)) {
                        message("Reusing ", object_name, " from the environment")
                        return(obj)
                }
                warning("Existing ", object_name, " is not a ", class, "; reloading")
        }
        if (is.null(file) || length(file) != 1 || is.na(file) || !nzchar(file) || !file.exists(file))
                stop("Set a valid input path for '", object_name, "' in the user-editable configuration")
        obj <- readRDS(file)
        if (!is.null(class) && !inherits(obj, class)) stop("Input for '", object_name, "' must be a ", class)
        assign(object_name, obj, envir = .GlobalEnv)
        message("Loaded ", object_name, " from ", file)
        obj
}

feature_proportion <- function(seu, feature = "orig.ident", loc = "region") {
        seu@meta.data %>%
                filter(!is.na(.data[[loc]]), .data[[loc]] != "void") %>%
                group_by(across(all_of(c(feature, loc)))) %>%
                tally() %>%
                ungroup() %>%
                group_by(across(all_of(feature))) %>%
                mutate(percent_feature = 100 * n / sum(n)) %>%
                ungroup()
}

plot_proportions <- function(df_proportion, feature = "orig.ident", loc = "region", y = "percent_feature", cols, y_lab = "Proportion") {
        ggplot(df_proportion, aes(x = .data[[feature]], y = .data[[y]], fill = .data[[loc]])) +
                geom_col(width = .95) +
                ylab(y_lab) +
                scale_fill_manual(name = NULL, values = cols) +
                scale_y_continuous(expand = expansion(mult = c(0, 0.05))) +
                theme_minimal() +
                theme(axis.text.x = element_text(size = 8, colour = "black", angle = 45, hjust = 1),
                      axis.title.x = element_blank(),
                      axis.text.y = element_text(size = 10, colour = "black"),
                      axis.title.y = element_text(size = 12, colour = "black"),
                      panel.grid = element_blank(),
                      axis.line = element_line(colour = "black"),
                      axis.ticks = element_line(colour = "black"),
                      axis.ticks.length = grid::unit(0.15, "cm"),
                      legend.title = element_blank(),
                      legend.background = element_rect(colour = "black", fill = NA))
}

split_and_recode_ilae <- function(df, ilae_col = "smpl_ILAE") {
        df %>%
                separate(all_of(ilae_col), into = c("smpl", "ILAE"), sep = "_(?=[^_]+$)") %>%
                mutate(ILAE = recode(ILAE, "0" = "ILAE0", "1" = "ILAE1", "2" = "ILAE2", "3" = "ILAE3"),
                       ILAE = factor(ILAE, levels = cfg$ILAE_levels))
}

### 3) Load input --------------------------------------------------------------
# 07_seumerged.rds is created in Section 8 of 01_domainIdentification.R.
# It contains PRECAST region and manually corrected region_md annotations.
seumerged <- load_if_missing("seumerged", cfg$seumerged_file, class = "Seurat")
if (!inherits(seumerged, "Seurat")) stop("'seumerged' must be a Seurat object")
required_cols <- c("region", "region_md", "ILAE_score", "smpl_ILAE")
missing_cols <- setdiff(required_cols, colnames(seumerged@meta.data))
if (length(missing_cols)) stop("Missing required seumerged metadata: ", paste(missing_cols, collapse = ", "))

seumerged$region <- factor(seumerged$region, levels = cfg$region_levels)
seumerged$region_md <- factor(seumerged$region_md, levels = cfg$region_levels)

### 4) Region proportions per ILAE score and per case -------------------------
# Uses manually corrected region_md, as in the original script.
seumerged_ILAE_reg_proportion <- feature_proportion(seumerged, feature = "ILAE_score", loc = "region_md") %>%
        mutate(ILAE_score = recode(as.character(ILAE_score),
                                   "P" = "Post", "0" = "ILAE 0", "1" = "ILAE 1", "2" = "ILAE 2", "3" = "ILAE 3"))

p <- plot_proportions(seumerged_ILAE_reg_proportion, feature = "ILAE_score", loc = "region_md", cols = cfg$col_regions)
ggsave(filename = file.path(cfg$fig_dir, "01_region_proportion_per_ILAE.png"), plot = p, dpi = 300, width = 5, height = 6)

seumerged_case_reg_proportion <- feature_proportion(seumerged, feature = "smpl_ILAE", loc = "region_md")
p <- plot_proportions(seumerged_case_reg_proportion, feature = "smpl_ILAE", loc = "region_md", cols = cfg$col_regions)
ggsave(filename = file.path(cfg$fig_dir, "02_region_proportion_per_case.png"), plot = p, dpi = 300, width = 12, height = 6)

n_spots_regions <- seumerged_case_reg_proportion %>%
        split_and_recode_ilae(ilae_col = "smpl_ILAE") %>%
        select(-percent_feature)
saveRDS(n_spots_regions, file.path(cfg$rds_dir, cfg$f_n_spots_regions))
message("Saved spot-count table to: ", file.path(cfg$rds_dir, cfg$f_n_spots_regions))

